    firstPanelSize: { control: { type: "range", min: 10, max: 90, step: 5 } },
    showHandle: { control: "boolean" },
  },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
